const error = $input.item.json;

// Error Trigger passa: error.execution.error
const execution = error.execution || {};
const errorObj = execution.error || {};
const nodeExecuted = execution.lastNodeExecuted || 'unknown';
const workflow = error.workflow || {};

const errorMessage = errorObj.message || 'No error message';
const errorType = errorObj.name || errorObj.code || 'unknown_error';
const nodeName = nodeExecuted;
const stackTrace = errorObj.stack || null;
const executionId = String(execution.id || '');
const workflowName = workflow.name || 'GHL Conversas';

// Tentar extrair dados do contexto original (se disponível)
const inputData = error.inputData || {};
const mainData = inputData.main?.[0]?.[0]?.json || {};
const contactId = mainData.contact_id || mainData.body?.contact_id || null;
const conversationId = mainData.conversation_id || null;

return [{
  json: {
    workflow_name: workflowName,
    execution_id: executionId,
    error_type: errorType,
    error_message: errorMessage,
    node_name: nodeName,
    contact_id: contactId,
    conversation_id: conversationId,
    stack_trace: stackTrace,
    full_error: error  // Objeto completo do Error Trigger
  }
}];

const input = $input.item.json;

// Construir o body do Supabase
const body = {
  workflow_name: input.workflow_name || 'unknown',
  execution_id: String(input.execution_id || ''),
  error_type: input.error_type || 'unknown_error',
  error_message: input.error_message || 'No error message',
  node_name: input.node_name || 'unknown',
  contact_id: input.contact_id || null,
  conversation_id: input.conversation_id || null,
  stack_trace: input.stack_trace || null,
  full_error: input.full_error  // Objeto completo - será serializado pelo n8
};

return [{
  json: body
}];
